@Configuration
public class WebSecurityConfig {

    @Bean
    SecurityFilterChain webSecurity(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/assets/**", "/signup").permitAll()
                .anyRequest().authenticated())
            .formLogin(form -> form
                .loginPage("/login")              // controller renders this page
                .loginProcessingUrl("/authenticate") // Spring processes this POST
                .usernameParameter("email")
                .defaultSuccessUrl("/dashboard")
                .failureUrl("/login?error")
                .permitAll());

        // CSRF remains enabled for this cookie-and-session browser flow.
        return http.build();
    }
}

@Configuration
public class SecurityConfig {

    @Bean
    SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
            .formLogin(form -> form
                .loginPage("/login")
                .failureHandler(jsonFailureHandler())
                .permitAll());
        return http.build();
    }

    @Bean
    AuthenticationFailureHandler jsonFailureHandler() {
        return (request, response, exception) -> {
            // Record a safe internal event if needed, but keep the public result generic.
            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            response.setContentType("application/json");
            response.getWriter().write("{\"error\":\"Authentication failed\"}");
        };
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .formLogin(Customizer.withDefaults())
            .logout(logout -> logout
                .logoutUrl("/api/logout")  // Custom logout URL
                .invalidateHttpSession(true)  // Destroy session
                .deleteCookies("JSESSIONID", "remember-me")  // Remove cookies
                .clearAuthentication(true)  // Clear SecurityContext
                .logoutSuccessHandler((request, response, auth) -> {
                    response.setStatus(HttpStatus.OK.value());
                    response.getWriter().write("{\"message\":\"Logged out successfully\"}");
                })
            );
        return http.build();
    }
}

